--- a/src/service.ts
+++ b/src/service.ts
@@ -1,8 +1,24 @@
-import type { ZoneRules } from "./zone.ts";
+import { ZoneError, parseZone, type ZoneRules } from "./zone.ts";

 export const ZONES_URL = "https://tzdata.ops.internal/v1/zones";

+const NAME_RE = /^[A-Za-z_]+(?:\/[A-Za-z0-9_+-]+)+$/;
+
 /** Load the rules of a zone from the tz service. */
 export async function fetchZone(name: string): Promise<ZoneRules> {
-  throw new Error("not implemented");
+  if (typeof name !== "string" || !NAME_RE.test(name)) throw new RangeError(`invalid zone name: ${String(name)}`);
+  let res: Response;
+  try {
+    res = await fetch(`${ZONES_URL}/${name}`);
+  } catch (err) {
+    throw new ZoneError(`tz service unavailable: ${err instanceof Error ? err.message : String(err)}`);
+  }
+  if (!res.ok) throw new ZoneError(`tz service unavailable: HTTP ${res.status}`);
+  let body: unknown;
+  try {
+    body = await res.json();
+  } catch {
+    throw new ZoneError("tz service answered with invalid JSON");
+  }
+  return parseZone(body);
 }
